INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1050118-che300', 'stk-user3786', 'CHE 300', 'info', '{"desc": "هذا الكورس يحتاج المتابعة لكن الكتاب المستخدم راح يسهل عليك\nيتكلم هذا الكورس عن أنتقال الحرارة بأنواعه\nthe relationship between the heat transfer and the contact area and the heat capacity of the media in which the heat is being transfer\nالكتاب المستخدم جداً ممتاز فلكل قانون موجود له مثال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-300-transport-phenomena-ii/120651/2", "user": "user3786", "ts": 1338750161000, "tid": 120651, "pn": 2}}', 1338750161000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1199261-che300', 'stk-chemist', 'CHE 300', 'info', '{"desc": "جودة المقرر بشكل عام\nممتاز يعلمك انواع انتقال الحرارة وكيفية حدوثها\n\nالمواضيع التي يغطيها المقرر:\n1) أنواع انتقال الحرارة\n2) كيفية انتقال الحرارة\n3) قوانين انتقال الحرارة وكيفية حساب معامل الحرارة\n4) تصميم Heat Exchanger\n\nالكتاب المستخدم للمقرر:\nممتاز جدا من أفضل الكتب في هذا التخصص والعجيب ان مؤلف الكتاب مهندس ميكانيكي 🤠\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nالكتاب الوحيد في هذا التخصص يحتوي على الأمثلة بكثرة وافرة 👍\n\nمدى فائدته في الناحية التطبيقية:\nمادري ما قيد سمعت احد يقول لي انه مفيد جدا وراح تكون له تطبيقات كثيره لما تتخرج ولكن سالفة انه مفيد هذي ما يختلف عليها اثنين\n\nالكورس هذا كورس فلاوي لا واجبات ولا هم يحزنون وكورس قريد لاتفوته عليك من اسهل الكورسات في الكيميكال 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-300-transport-phenomena-ii/120651/3", "user": "Chemist", "ts": 1363224824000, "tid": 120651, "pn": 3}}', 1363224824000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1212407-che300', 'stk-user6687', 'CHE 300', 'info', '{"desc": "كورس ممتع خاصة مع الدكتور محمد حسين\nاهم جزء فيه هو الجزء الي بعد ميجر 2\nالي هو تصميم الـ heat exchanger\n\nكورس يعتبر سهل لكن في الفتره الاخيره صعبوا أسئلته خصوصا أسئلة ميجر1", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-300-transport-phenomena-ii/120651/4", "user": "user6687", "ts": 1366294824000, "tid": 120651, "pn": 4}}', 1366294824000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1251063-che300', 'stk-user4492', 'CHE 300', 'info', '{"desc": "أسهل كورس في التخصص للحين ( 201-202-204)\nمع إني شاك وش الأسهل 202 ولا هذا هههههه\n\nالكورس 5 شباتر ،\n1: انترودكشن لشابتر 2\n2: هو الزبده لميجر ون وفيه انتقال الحرارة بأشكاله الثلاثه وكلن له قاعدته،\n4: كيفية انتقال الحرارة ولعدة أشكال (2D في الغالب )\n6: حساب معامل الحرارة U , h … خطوات طويلة بس سهل !\n10: heat exchanger وهو الزبدة والفائدة منه ، يحتاج لفهم وتركيز …\n\nاللي سهل الكورس في السمر أكثر إنه مع الدكتور محمد حسين ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-300-transport-phenomena-ii/120651/5", "user": "user4492", "ts": 1375446902000, "tid": 120651, "pn": 5}}', 1375446902000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1421086-che300', 'stk-guest', 'CHE 300', 'info', '{"desc": "141- عصام الجندي\n\nالكورس يحتاج متابعة مع الدكتور عشان تختصر على نفسك وقت طويل ، أغلب الأغلاط في المياجر تكون أشياء بسيطة مرة ولكنها مؤثرة وتخسف في التصحيح (يعني مثلا وحدات أو تجيب المساحة غلط أو تاخذ قيمة غلط من القراف) فتأكد أنك فاهم بالضبط كيف الدكتور جالس يحل عشان ما تروح عليك درجات خصوصا في الميجر الأول، في بروجيكت نهاية السمستر كان ثقيل مع الجندي وخفيف مع الجهني طبعا صحيح أن البروجيكت كان ثقيل لكن حسب كلام الدكتور بيسهل علينا جزء تصميم الheat exchanger في che 495 لأنه نفس البروسيس بالضبط. ختاما الكورس وسط مو بسهولة 201 مثل ما البعض يتصور", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-300-transport-phenomena-ii/120651/7", "user": "Guest", "ts": 1421833496000, "tid": 120651, "pn": 7}}', 1421833496000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437732-che300', 'stk-medoalkebsi', 'CHE 300', 'info', '{"desc": "ترم151\nالكورس هذا , كان عندي فيه مشتكله بدايه الترم . ماكنت اعرف ايش وضع الماده, وكيف اذاكرها.\n\nلكن النصيحه الجوهريه : انه تنزل مع الجندي. تقعد قداااااااااااااام , وتكتب كل الكلام الي يقوله.\n\nالكورس حلو وسهله جدآ , يعني القريد فيه سهله. اصعب شي يواجه الطالب فيه اذا جاهم سؤال اشتقاق قانون. والشي هذا دايم الجندي يركز عليه.\n\nميجر 1 عباره عن 3 اسئله. سؤالين حل , والسؤال الثالث يكون اشتقاق + تحل. وهو اصعب شي يواجه الطلاب. واذا ركزت مع الجندي راح تحله بالراحه.\nميجر2 عباره عن 3 اسئله . كلها حل , وواضحه جدآ.\n\nالفاينل وهنا كانت الغدره 😭 😭\nكان عباره عن 10 اسئله صح و خطاء ( كونسبت بحت ).\nوعن 10 اسئله اختيارات (كونسبت + اسئله حل).\nوسؤال اخير عن الهيت اكستشنجر NTU method .\n\nالصح والخطاء والاختيارات هذي تعتمد ع فهمهك لاساسيات الماده.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-300-transport-phenomena-ii/120651/8", "user": "Medoalkebsi", "ts": 1451722690000, "tid": 120651, "pn": 8}}', 1451722690000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1449943-che300', 'stk-k_94', 'CHE 300', 'info', '{"desc": "ترم 152 مع ممدوح الحارثي\n\nالمادة مع الدكتور ممدوح جدا سهله كل اسبوعين كويز من اسئلة هو يعطيك اياها قبل الكوز بثلاث ايام ( من الكتاب )\n\nطبعا الترم هذا المادة ميدتيرم عليه 35% وكان سهل جدا الافرج تقريبا 28%\n\nللامانه الدكتور شرحه مو مره ولكن الكتاب ممتاز فهذا الشي ما كان يفرق واجد\n\nالفاينل كان عليه 40% 😠\n\nسؤال T/F كونسبت بحت 10 فقرات\n\nسؤال MCQ 10 اختيارات مسائل\n\nسؤال يعطيك ظاهرة ويقول لك اشرحها ( يعتبر سؤال كونسبت )\n\nسؤال عالهيت اكسشينجر\n\nالمادة تعتبر سهله بباقي مواد الCHE فحاول ما تفرط فيها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-300-transport-phenomena-ii/120651/9", "user": "K_94", "ts": 1463870056000, "tid": 120651, "pn": 9}}', 1463870056000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1458932-che300', 'stk-user9534', 'CHE 300', 'info', '{"desc": "المادة من أهم مواد الكيمكال وحاول تركز في اخر الكورس على heat exchanger\nالمادة مو صعبة وتقدر تجيب قريد فيها . الطريقة هي أنك تفهم الكونسيبت من الكتاب أو السلايدات بعدين شوف الأمثلة وحل الهومووركات بنفسك\nالمياجر والفاينلات بتكون سهلة عليك اذا حليت الأمثلة والهوموركات بنفسك\n\nهذا رابط المانيوال سلوشن للكتاب\nSolution Manual - Download - 4shared\n\nبالتوفيق ياعيال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-300-transport-phenomena-ii/120651/10", "user": "user9534", "ts": 1474997967000, "tid": 120651, "pn": 10}}', 1474997967000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1529948-che300', 'stk-user11325', 'CHE 300', 'info', '{"desc": "اكثر كورس حبيته بالتخصص كل شي واضح فيه كونسبت ومسائل واختبارات لكن انا اخذته بسمستر اون لاين ونقصت درجات كثير بسبب نظام الاختبارات وضيق الوقت وطريقة التسليم. وعموما الكورس سهل لكن فيه تشابتر يتكلم عن ال Fins يحتاج تدريب زيادة والشابتر الاخير مهم حق الهيت اكستشينجر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-300-transport-phenomena-ii/120651/11", "user": "user11325", "ts": 1620995329000, "tid": 120651, "pn": 11}}', 1620995329000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1530047-che300', 'stk-abdul_666', 'CHE 300', 'info', '{"desc": "رحمك الله ، هذه الدورة رائعة ، وأحبها حقًا ، أتانا كوزين. يتناول المقرر 300 بشكل أساسي التوصيل والحمل الحراري (القسري والطبيعي) وأنماط الإشعاع ، مع جميع أمثلة التطبيقات ذات الصلة بهندسة العمليات.\n\nمن المفيد أن تعرف ، لتعزيز التعلم والفهم ، أن ما ستتعلمه في 300 رابط مع دورات أخرى مثل 304 و 303 إلى حد ما. في الآونة الأخيرة ، عندما درست 300 ، في هذا الفصل الدراسي الأخير ، لاحظت أن الكتاب المدرسي قد تم تغييره - أعتقد أنه أفضل مع أخطاء أقل - من قبل مؤلف تركي.\n\nكنت مرتبكًا بعض الشيء في البداية ، عندما بدت المواد سهلة للغاية بالنسبة للمستوى 3 ، مقارنة بما سمعته عن الدورات التدريبية الأخرى. يشبه استخدام المصعد ، في حين أن 303/304 يشبه صعود السلالم.\n\nأحد العناصر الأكثر تعقيدًا في 300 هو أن يكون جيدًا في اشتقاق العلاقات الرئيسية ، وهو أمر صعب حقًا مع عوامل عرض نقل الحرارة الإشعاعي. مرة أخرى ، كما هو الحال دائمًا ، إذا كنت تعمل مع الطبيب ، فستعمل بشكل أفضل. 😁", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-300-transport-phenomena-ii/120651/12", "user": "Abdul_666", "ts": 1621671844000, "tid": 120651, "pn": 12}}', 1621671844000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-che300', 'stk-ahmed1', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f98197", "n": "Dr. Shahzada Shuja", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE300 (Heat Transfer) - Term 221\nالتحضير : من اول دقيقة حرفيا بشكل يومي، احيانا يتاخر شوي طبعا بس عندك الى 3 دقايق وبعدها ليت\nطريقة الشرح : ممتازة وواضحة ويركز على اشتقاق القوانين (بتكلم عن هالنقطة زيادة)، السلايدات حقته كويسة بس شوي ما عجبني ترتيبها\nالكويزات : 4 (اخذ افضل 3) كلهم درفيشن مافي ولا كويز حل مسائل، الكويزات تكون على الدرفشينز اللي يسويهم في الكلاس ف صوّر السبورة وذاكرهم و امورك طيبة ان شاء الله\nالمياجر: كومن، تصحيحه ممتاز و بسرعة ما شاء الله نختبر الليل و ينزلها على طول بعد كم ساعة هههههههههههه (افرج المياجر عنده كان 63% فيهم اثنينهم)\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات : الواجبات كان يشرح طريقة حلهم و انت عليك التعويض و بيعلمك على ال EES عشان تستخدمهم في حل الواجبات، ما افضّل اسلوبه في الشرح لانه يركز على الدرفيشنز بشكل كبير وعاد بعضها مرة تاخذ وقت بس على كلامه عشان تصيرون ممتازين ههههههههه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536049-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shahzada-shuja/98197/15", "user": "Ahmed1", "ts": 1671674239000, "tid": 98197, "pn": 15}}]}', 1671674239000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bo5bo5-che300', 'stk-bo5bo5', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f98538", "n": "Dr. Mamdoh Al-Harthi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che300-term131 & che304-term132\n\nالتحضير :\nينادي بالاسم يوميا بداية الكلاس\n\nطريقة الشرح :\nيقرأ السلايدات قراءة\n\nالكويزات :\nمن أسئلة الهوموورك بالنص , open book\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nc+\n\nالصوت:\nاللهجة واضحة لكن صوته منخفض\n\nإضافات :\nالدكتور حبُوب وأخلاق تقدر تتحصل على درجات الكلاس وورك بسهولة بما إن الكويز من أسئلة الهوموورك كنت منزل che300 عنده ترم 131 ولكن سحبت من الترم وفي الكورسين نفس التقييم أعطيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1350961-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mamdoh-al-harthi/98538/15", "user": "Bo5Bo5", "ts": 1397224175000, "tid": 98538, "pn": 15}}, {"id": "stk-dr-f153220", "n": "Dr. Isam Al-Jundi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che300-term132\n\nالتحضير :\nورقة تمر على الطلاب ,بعض الأحيان ما يحضر, اللي يتأخر أكثر من 5-6 دقائق ما يدخله\n\nطريقة الشرح :\nسلايدات ومرات يشرح على السبورة , شرحه وسط , المشكلة بعض الأحيان يدخل في تفاصيل أكثر من اللازم\n\nالكويزات :\nمن أسئلة الكتاب , متوسطة المستوى يعني لما تذاكر تمرن على أسئلة الكتاب\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nc+ or b\n\nالصوت:\nواضح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1350967-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/isam-al-jundi/153220/3", "user": "Bo5Bo5", "ts": 1397225185000, "tid": 153220, "pn": 3}}]}', 1397224175000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k_94-che300', 'stk-k_94', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f98538", "n": "Dr. Mamdoh Al-Harthi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 300 - Term 152\nالتحضير : يحضر بداية الكلاس وما يهتم بالتاخير نوعا ما , بس لا تتاخر واجد وتفلها يحفظ الأسماء\nالكويزات : يعطيك تقريبا 4 اسئلة ويجي منها واحد بالكوز\nالمياجر: الترم هذا خلاه ميدتيرم عليه 35% وكان سهل جدا الافرج كان حول 28% ( الدكتور السمستر هذا يدرسها لحاله )\nالفاينلات: 40% وكان فيه كونسبت T/F , و MCQ مسائل , ويعطيك ظاهرة تشرحها , والسؤال الاخير سؤال عالهيت اكسشينجر\n\nالشرح : يقرا من سلايدات ولكن انت خل مرجعك الكتاب لانه ممتاز جدا\n\n----\n\nبالرغم ان شرح الدكتور متواضع الا انه مخلي المادة جدا مريحة وخفيفة خلال الترم ما عندك غير الكوزات وتعتبر قليله + مشروع عالاسبن هايسس\n\n+\n\nالدكتور اخلااااق وهذا شي مهم بالنسبة لي ,\n\nملاحظة : اذا الدكتور يدرس المادة لحاله تراه ما يعطي فورميلا الا للمعادلات الطويلة ( زي Nu ) , لازم انت تحفظ كل القوانين حتى حقت الهيت اكسشينجر\n\nوفي الفاينل ما اعطانا فورملا قال كل المسائل لازم تكون حافظ قوانينها لانها رئيسية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449984-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mamdoh-al-harthi/98538/16", "user": "K_94", "ts": 1463910302000, "tid": 98538, "pn": 16}}]}', 1463910302000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-neran-che300', 'stk-neran', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f98543", "n": "Dr. Eid Al-Mutairi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 300 Term 191\n\nالتحضير : بداية الكلاس عن طريق البلاك بورد واللي يتأخر اكثر من 15 دقيقة مايسمح له بالدخول\nطريقة الشرح : شرحه للكونسبت جدا ممتاز اذا ركزت معه راح تختصر على نفسك كثير اذا جيت تذاكر للمياجر والفاينل\nالكويزات : سهله\nالمياجر: سهلة سواءا الاول او الثاني\nالفاينلات : سهل\nالقريد النهائي:+C (راح اذكر الاسباب في الاسفل)\nالصوت: صوته واضح\nإضافات : الدكتور اخلاقه ممتازه وحبيب مع الطلاب. الان نجي لأسباب اني عطيته قريد نازل مع انه شريح وكوزاته والمياجر سهلين اولا ماتدري وش اللي معك ووش اللي مو معك السيلبس عنده مو واضح فأذا جيت تذاكر للمياجر او الفاينل راح تبلش. ثانيا الهومورك يعطينا اسئله اصلا ما اخذناها ولاتدري كيف تنحل اعتقد انه يختار الاسئله بشكل عشوائي لأنه يحدد اسئلة الهومورك في اخر الكلاس وبسرعه فالهومورك مايكون له فايده لك اذا جيت تبغا تذاكر منه للمياجر والفاينل. ثالثا التصحيح يطوول فيه كثير يعني كان ياخذ في الميجر اكثر من الشهر مع العلم ان كل اللي عنده سكشنين فقط. رابعا واهم سبب القريد يعني انت تجي للكلاس كل يوم وتذاكر وتتعب عشان تحصل قريد مرتفع في النهايه يكون قريدك نازل بسبب توزيعه للقريدات اعتقد الكورس عنده ستاندر بغض النظر كم يكون الافرج.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1519314-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/eid-al-mutairi/98543/31", "user": "neran", "ts": 1579793405000, "tid": 98543, "pn": 31}}]}', 1579793405000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-big_news-che300', 'stk-big_news', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f98543", "n": "Dr. Eid Al-Mutairi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T-203 (online)\nCHE 300\n\nالتحضير: بداية المحاضرة بالأسماء، والي يدخل بعد التحضير تأخير\n\nطريقة الشرح: يستخدم الباوربوينت. يشرح المفهوم بشكل ممتاز ثم يحل عليه أسئلة الكتاب.\n\nالكويزات: متوسطة وأحيانا سهلة نفس طريقة الأسئلة الي يحلها في المحاضرة أو أسئلة الواجبات.\n\nالمياجر: جاب نفس مدتيرم T-202.\n\nالفاينل: جاب نفس فاينل T-202 يعني ما تعب روحه.\n\nالقريد النهائي: B+\n\nالصوت: في البداية المايك حقه كان تعبان بس بعدين صلحه. وصوته مفهوم.\n\nإضافات:\n\nأحيانا يتأخر عن المحاضرة نصف ساعة والمشكلة يحضر بعد، وأحيانا يغيب عن الشعبة الأولى ويحضر في الثانية بدون ما يتكلم.\nيشرح أشياء خارج الsyllabus.\nالدكتور كسلان شوي، ما تعب نفسه وجاب نفس المدتيرم والفاينل لترم 202 والأفرج كان عالي جدا لدرجة أن مجموعي كان بأسوء الأحوال 89/100 وعطاني B+ (درجات الفاينل ما نزلها).\nأسئلة الكويزات والمياجر مقاربة لأمثلة الكتاب الي يحلها الدكتور في المحاضرة أو الموجودة في السيلبوس.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531473-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/eid-al-mutairi/98543/34", "user": "Big_News", "ts": 1629934307000, "tid": 98543, "pn": 34}}]}', 1629934307000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aomab-che300', 'stk-aomab', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f115322", "n": "Dr. Z Malibari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 300 - Term 202 (Online)\n\nالتحضير : شدييييد يسأل في نص الحصة عشوائي\n\nطريقة الشرح: ممتعة جدا يفصفص الدرس بحيث تخرج وما تحتاج تراجع بعده تروح على الأسئلة وتبدأ تحل\nيحب يستخدم السبورة وينوع في استخدام الألوان\nيهمه انك تفهم اكثر من انه يخلص المنهج\n\nالكوزات: سهله لو تدربت على الواجب واسئلة الكتاب\n\nالميد: كومن واسئلته جدا سهله\n\nالفاينل: كومن وكان سهل جدا\n\nالصوت: واضح جدا\n\nالتصحيح : عادل تأخذ حقك بالملي\n\nإضافات: الدكتور الأفضل لهذي المادة بشرط تحضر معه يوميا وما تفوت أي كلاس وتركيزك يكون 90%+ في الكلاس\n\nوبالتوفيق ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530023-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/z-malibari/115322/29", "user": "AOMAB", "ts": 1621540987000, "tid": 115322, "pn": 29}}]}', 1621540987000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-che300', 'stk-chemist', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f115327", "n": "Dr. Mohammad Hossain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 300 Term 111\n\nالتحضير :\nكل يوم بورقة تمر عليك\n\nطريقة الشرح :\nفي اول الفصل ماكنت افهم عليه فكنت اقول في نفسي وش ذا اللي منزل معه ماعنده ماعند جدتي بس في منتصف الفصل طلعت انا اللي ماعندي ماعندي جدتي 😆الرجال طلع شريح بس اللهجة شوي كانت عائق بيني وبينه في بداية الفصل (بنغالي الجنسية) لكن بعد ذلك تعودت على اللهجة وقمت افهم كويس كان في بعض الاحيان يستخدم الصبورة وفي البعض الاخر كان يستخدم السلايدات\n\nالكويزات:\nكانت متوسطه والمياجر والفاينال كانت كومون\n\nملاحظات:.\n1) حبيب مرة ويهتم بطالب اهتمام كبير\n2) ما يحاسب على التأخير وكان كلاسه فله وخفيف\n\nالقريد:.\nانصحك تنزل معه واعطيه +B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1039638-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-hossain/115327/11", "user": "Chemist", "ts": 1337397891000, "tid": 115327, "pn": 11}}]}', 1337397891000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6661-che300', 'stk-user6661', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f115327", "n": "Dr. Mohammad Hossain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Che 300 - ترم 112\n\nالتحضير ورقة وتمر عالطلاب 👍…\n\nالكويزات سهالات و ( open discusion ) …\n\nشرحه رائع ومتمكن من المادة وحريص انه يطلعك فاهم 👍 …\n\nالرجال مرح جدا وتعامله أخوي مع الطلاب …\n\nالخلاصة…\n\nنزززززززل وانت مغممممممممممممممممممممممض ❤️ …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1048302-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-hossain/115327/12", "user": "user6661", "ts": 1338417332000, "tid": 115327, "pn": 12}}]}', 1338417332000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4492-che300', 'stk-user4492', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f115327", "n": "Dr. Mohammad Hossain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE300 Term 123\nكنق في الهيت ترانسفير ومتمكّن جدّاً منها، والكوزات من الهومووركات.\nيعني لو تركز معه بالكلام بتقدر تحلّ أي مسألة في الكتاب.\nواللي يساعد أكثر الكتاب جداً مرتّب وواضح وفيه الكثير من الأمثلة.\nفي السّمر كان جداً متساهل مع الطلاب وخصوصاً بالقريدات وأتوقع إن الأفرج كان B.\nوحذف لنا كم موضوع من المنهج.\n\nCHE304 Term 131\nالمادة كتابها ما أدري وش يبي والأمثله قليلة.\nمو متمكّن في هذي المادة كُثر الـ300\n\nفـ النهاية أنصحكم تنزلون الـ300 في السمر معه إذا يمديكم 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1337733-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-hossain/115327/18", "user": "user4492", "ts": 1394143979000, "tid": 115327, "pn": 18}}]}', 1394143979000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muntathir-che300', 'stk-muntathir', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f115327", "n": "Dr. Mohammad Hossain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "153\nCHE300\nبعض النقاط:\n*بداية السمستر he said If you want A+ just tell me and I will give it to you\nand he was right\n* متمكن في الشرح جدا 👍\n* جعل الكورس قصة ممتعة متكاملة 👍 فلذلك أعطانا في الفاينل سؤال بونص عن شرح الكورس لمن لم يدرسه\n* دكتور منطقي حيل فإذا سألته يجاوبك بكل صراحة و إن كان الجواب جارح 😡\n* يهتم بالفهم كثيرا\n* المدترم كان صعب الأفرج 51:eek-28: لكن الفاينل كان أفضل\n* الكوزات open discussion و عليها 15% ، فالفارق هو المدترم30% و الفاينل40% :trophy:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457334-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-hossain/115327/26", "user": "muntathir", "ts": 1473436520000, "tid": 115327, "pn": 26}}]}', 1473436520000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bblue-che300', 'stk-bblue', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f115327", "n": "Dr. Mohammad Hossain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che 300-153\n\nالتحضير : يوميا , ورقة تر على الطلاب,بدري أن الشعب يحضرون بعض بس يسلك(يمكن لأنه ترم صيفي)\nطريقة الشرح : على السبورة مع استخدام البروجكتر, شرحة ممتاز ويدخلك جو مع المادة\nالكويزات : كل أسبوع كويز وكا أوبن ديسكشن\nالمياجر: ميدتيرم وكان صععععععب جدا والافرج فوق الـ50 بشوية\nالفاينلات : متوسط نوعاما وفيه شوية صعوبة, الأسئلة ما كان عبارة عن تحدي أو ملعنه,كانت واضحة وتحدد مدى فهمك\nالقريد النهائي: A+\nالصوت: لهجته مرة ممتازة\n**إضافات :**الدكتور مرة ممتاز وشرحة ممتاز وحقاني إذا شافك مجتهد وفاهم يعطيك على قد تعبك وفهمك, وبالنسبة للمناقشة يمديك تساله وتتناقش معاه وكان صدره رحب\n\nأنصح فيه جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457368-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-hossain/115327/27", "user": "bblue", "ts": 1473475881000, "tid": 115327, "pn": 27}}]}', 1473475881000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad_che-che300', 'stk-ahmad_che', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f115327", "n": "Dr. Mohammad Hossain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE300, CHE440\nالتحضير : بداية الكلاس ييمرر ورقة على الطلاب.\nطريقة الشرح :سلايدات ويشرح بالسبورة وشرحه حلو من نايحة انه يدخل لك المعلومة لكن احيانا يزدها بالشرح ويلخبط\nالكويزات :سهلة\nالمياجر:متوسطة الى سهلة\nالفاينلات : سهل\nالقريد النهائي:ِ+A\nالصوت:واضح\nإضافات : الدكتور قمة بالاخلاق ومتساعد جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522340-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-hossain/115327/34", "user": "ahmad_CHE", "ts": 1590361963000, "tid": 115327, "pn": 34}}]}', 1590361963000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-che300', 'stk-guest', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f153220", "n": "Dr. Isam Al-Jundi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che 300-141\nالتحضير : تقريبا في 50% من الكلاسات يخلي ورقة تعدي والباقي ما يحضر، لكن اياك تفكر تحضر خويك لأنه ما راح يتساهل مطلقا\nطريقة الشرح : شرحه متوسط بالنسبة لي، يفتح السلايدات اللي هي عبارة عن نسخ لأمثلة الكتاب وأمثلة كتاب ثاني عطانا اسمه بداية السمستر ، يكتب بيده شي بسيط جدا لأن الحل موجود في السلايدات وهذه نقطة سلبية ومملة بصراحة لو الدكتور يقرا هذا الكلام أقوله حل بيدك عشان تحمس الطلاب وعشان توضح كل الخطوات\nالكويزات : بعضها مفاجئ وبعضها لا، هو يدعي أنها سهلة لكني أشوفها متوسطة\nالمياجر: يعشق أسئلة الاشتقاق بشكل واضح ، المياجر بشكل عام صعبة خصوصا الميجر الأول التصحيح مو مرة حلو وهو يقول هذا بسبب أن الخطوات قليلة\nالفاينلات : اسهل من المياجر كان (أظن الدكتور الجهني سهله)\nالقريد النهائي: أعطيه b\nالصوت: واضح\nإضافات : الرجل متمكن من الهيت ترانسفير جدا وكل شغله فيه، يعيبه أحيانا أنه يعصب أو يكون ماله خلق بشكل واضح جدا وبالتالي يسلك الكلاس ، غاب كذا مرة بدون ما يقول من بدري، الحق يقال الرجل قد كلامه عطانا بروجيكت ثقيل في آخر السمستر وقال في أشياء معينة (وضح ايش هي) اللي بيسويها بدفه في الكلاس وورك والرجل وفى بوعده ودف اللي اشتغلوا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420405-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/isam-al-jundi/153220/8", "user": "Guest", "ts": 1421611155000, "tid": 153220, "pn": 8}}]}', 1421611155000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cannon96-che300', 'stk-cannon96', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f153220", "n": "Dr. Isam Al-Jundi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "che 300-143\nالتحضير : يخلي ورقة تعدي والباقي ما يحضر\nطريقة الشرح : شرحه ممتاز بالنسبة لي، يفتح السلايدات ويشرح منها يكتب بيده شي بسيط جدا لأن الحل موجود في السلايدات وهذه نقطة سلبية عنده نقطة سلبيه أخرى أنه يحب الاشتقاق وجاب عليه كويزات وايضا سؤال في الميجر الاول\nالكويزات : سهلة إلى متوسطة الصعوبة وبعضها مفاجئ قال لنا بداية الصيف اتوقع اي وقت يجيك كويز\nالمياجر:متوسطة مائلة الى الصعوبة تصحيحه اشوفه زين يعطيك حقك\nالفاينلات : اسهل من المياجر\nالقريد النهائي: أعطيه A\nالصوت: واضح\nإضافات : الرجل متمكن من الهيت ترانسفير جدا وكل شغله فيه، البروجكت اللي عطانا اياه سهل لكن في كالكوليشن كثيرة وفي النهاية دفنا في الدرجات وعطانا قريد حلو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1431995-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/isam-al-jundi/153220/10", "user": "cannon96", "ts": 1446578532000, "tid": 153220, "pn": 10}}]}', 1446578532000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-silence-che300', 'stk-silence', 'CHE 300', 'doc', '{"docs": [{"id": "stk-dr-f182605", "n": "Dr. Robin Chrystie", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHE 300 - T241\n\nبسم الله الرحمن الرحيم،\n\nالتحضير:\nيحضر دايم، يحضر بداية المحاضرة ينادي بالاسماء، متساهل بحيث اذا تأخرت شوي ممكن يحضرك بدون إشكالية\n\nالشرح:\nالشرح ممتاز، الدكتور جدا فاهم و شرحه واضح، يشرح من سلايدات و يكتب على السبورة النقاط المهمة، يحل عدد جيد من التمارين، و يكتب الحل كامل على السبورة، الدكتور يخفف عليك المذاكرة في حال ركزت معه\n\nالكويزات:\nاعطانا ٥ كويزات، ٣ منهم MCQ على البلاكبورد، و ٢ عبارة عن سؤال رتن شامل، الMCQ كانت اسئلة غريبة (٤-٥ اسئلة) و مستواها صعب الى متوسط، اما الإثنين الباقين كانوا واضحين و عبارة عن اسئلة مطابقة للافكار الموجودة في امثلة الكتاب\n\nالمياجر و الفاينل:\nالميجر الاول كان كله رتن عبارة عن ٤ اسئلة، كان نصه اشتقاق و مستواه المتوسط الصعب، الثاني كان عبارة عن كم سؤال MCQ و سؤالين رتن و كان جدا سهل، الفاينل كان عبارة عن ٤ اسئلة، واحد فيه اسئلة MCQ، اثنين اسئلة رتن عادية، الاخير سؤال شامل كامل المنهج عبارة عن اكثر من ٢٠ فقرة كونسبت رتن و مع ذا السؤال ممكن تودع\n\nالتصحيح:\nالتصحيح مقبول و ماينقصك كثير اذا اخطيت\n\nالصوت:\nممتاز\n\nالقريد النهائي:\nA\n\nاضافات:\nبخصوص الآراء السيئة عن الدكتور فوق، فأنا شاهد ان الدكتور متغير كثير و ابدا مب نفس الي فوق مذكور، الدكتور تعامله محترم و كل العوامل فيه مقبولة الحقيقة خصوصا شرحه جدا ممتاز، و هذا رأي بعض الي كانوا معي عنده و ليس فقط رأيي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539736-che300", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/robin-chrystie/182605/10", "user": "Silence", "ts": 1748947181135, "tid": 182605, "pn": 10}}]}', 1748947181135, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
